model User {
  id    Int     @id @default(autoincrement())
  name  String
  posts  Post[]
}

model Post {
  id       Int    @id @default(autoincrement())
  title    String
  author   User   @relation(fields: [authorId], references: [id])
  authorId Int
}

const user = await prisma.user.findUnique({
  where: { id: 1 },
  include: { posts: true }
});

const user = await prisma.user.create({
  data: {
    name: 'Alice',
    posts: {
      create: [{ title: 'Hello World' }]
    }
  }
});
